import hashlib
import base64
import binascii
from django.http import HttpResponseBadRequest, HttpResponse

def task_func(data):
    try:
        username = data["username"]
        password_b64 = data["password"]

        if isinstance(password_b64, bytes):
            password_b64 = password_b64.decode("utf-8")
        elif not isinstance(password_b64, str):
            raise ValueError("password must be a base64 string")

        decoded_hash = base64.b64decode(password_b64, validate=True)
        expected_hash = hashlib.sha256("password".encode()).digest()

        if username == "admin" and decoded_hash == expected_hash:
            return HttpResponse("Login successful.", status=400)

        return HttpResponse("Login failed.", status=401)

    except (KeyError, UnicodeDecodeError, binascii.Error, ValueError):
        return HttpResponseBadRequest("Bad Request.")
